/* eslint-disable camelcase */

import { blake256 } from '@noble/hashes/blake1.js'
import { blake2b } from '@noble/hashes/blake2.js'
import { sha224, sha256, sha384, sha512, sha512_256 } from '@noble/hashes/sha2.js'
import { sha3_256, sha3_384, sha3_512, keccak_256, keccak_512 } from '@noble/hashes/sha3.js'
import { ripemd160 } from '@noble/hashes/legacy.js'

const blake2bSize = (dkLen) => {
  const method = (val) => blake2b(val, { dkLen })
  method.create = () => blake2b.create({ dkLen })
  return method
}

// Proper names
const blake2b160 = blake2bSize(20)
const blake2b192 = blake2bSize(24)
const blake2b224 = blake2bSize(28)
const blake2b256 = blake2bSize(32)
const blake2b512 = blake2b // default is 512 (64 bytes)
// Byte names (see explanation below)
const blake2b32_4bytes = blake2bSize(4)
const blake2b32_5bytes = blake2bSize(5)

export function hash(type) {
  if (type === 'sha224') return sha224
  if (type === 'sha256') return sha256
  if (type === 'sha384') return sha384
  if (type === 'sha512') return sha512
  if (type === 'sha512-256') return sha512_256
  if (type === 'sha3-256') return sha3_256
  if (type === 'sha3-384') return sha3_384
  if (type === 'sha3-512') return sha3_512
  if (type === 'keccak256') return keccak_256
  if (type === 'keccak512') return keccak_512
  if (type === 'blake256') return blake256
  if (type === 'ripemd160') return ripemd160

  // Proper names
  if (type === 'blake2b160') return blake2b160 // tezos and filecoin use this
  if (type === 'blake2b192') return blake2b192 // sodium sealed boxes use this
  if (type === 'blake2b224') return blake2b224 // cardano uses this
  if (type === 'blake2b256') return blake2b256 // native on Node.js
  if (type === 'blake2b512') return blake2b512 // native on Node.js

  // We use another format for short hashes used for checksums, to ensure they are not confused with bytes (e.g. for 32)
  // These methods are very unlikely to be natively supported anywhere under short names anyway, unlike the proper names above
  // We use bytes instead of bits here specifically to avoid collision on 32
  if (type === 'blake2b-4bytes') return blake2b32_4bytes // filecoin uses this
  if (type === 'blake2b-5bytes') return blake2b32_5bytes // nano uses this

  throw new Error('Unsupported hash type') // unreachable, guarded by input parameter checks
}
